            // `:12515`, `:12527`, `:12531`); the arithmetic compound forms
            // reach it from the arm above, behind `leftOk && rightOk`. §543.
            Node::BinaryExpression(binary)
                if binary.operator_token.is_some_and(|t| t.kind.is_assignment_operator()) =>
