    /// upstream has none either; the callers memoise the types they build.
    pub fn get_symbol_of_part_of_right_hand_side_of_import_equals(
        &mut self,
        entity_name: NodeId,
    ) -> Option<SymbolId> {
        let mut entity_name = entity_name;
