    #[must_use]
    pub fn type_of(&self, id: TypeId) -> &crate::types::Type {
        self.store.get(id)
    }

    /// Read-only view of [`Checker::type_reference_targets`] — the
    /// `(symbol, arguments)` pair a reference was interned on.
