                    Some(self.signature_rest_type_at_position(&signature, index))
                } else {
                    self.signature_type_at_position(&signature, index).or_else(|| {
                        parameters[index]
                            .initializer
                            .is_none()
                            .then_some(self.intrinsics.undefined_widening)
                    })
                }?;
