                        for length in [None, Some(1)] {
                            assert_eq!(
                                tuple_context(
                                    &source,
                                    (strict, exact),
                                    warm,
                                    0,
                                    length,
                                    (None, None)
                                )
                                .as_deref(),
                                Some(expected),
                                "strict={strict} exact={exact} warm={warm} explicit={explicit} \
                                 tail={tail} length={length:?}"
