        use crate::relater::{Relation, Ternary};

        let arena = Arena::new();
        let source = r#"enum First { A = "a", B = "b" }
enum Second { A = "a", C = "c" }
declare function owner<U, T extends U extends string ? First : number>(value: T): [T];
const value = First.A;"#;
        let parsed = tsr_parser::parse(&arena, source);
