                    if !restore.contains(&t) {
                        restore.push(t);
                    }
                    continue;
                }
                if let TypeData::Union { types: constituents, .. } = &self.store.get(t).data
                    && constituents
                        .iter()
                        .any(|&c| self.store.get(c).flags.intersects(TypeFlags::NULLABLE))
