    // parameter is `errorType`, which prints `any` — exactly what a miss prints
    // — so a test on the printed line could not tell the gate from its absence.
    let source = "class C<T> { p: T; }";
    assert_eq!(property_of(source, "C", "T"), None);
    let (name, flags) = property_of(source, "C", "p").expect("`p` is a property");
    assert_eq!(name, "p");
    assert!(flags.contains(SymbolFlags::PROPERTY));
}

#[test]
fn implements_contributes_no_members() {
    // Upstream reads only the `extends` clause for base types
    // (`getEffectiveBaseTypeNode`). An `implements` clause is checked for
    // conformance and inherits nothing.
    let source = "interface B { p: number }\nclass C implements B { }";
    assert_eq!(property_of(source, "C", "p"), None);
}

#[test]
fn a_generic_base_keeps_its_declaration_origin_and_instantiated_property_type() {
    // This formerly pinned an honest unported gap. Native class reference
    // admission (5b1047d checker.go:19220) applies B<number>; the new publication
    // path now owns both the origin and the concrete member read. Testing only
    // the returned name would hide a raw T in place of number.
    let source = "class B<T> { p: T; }\nclass C extends B<number> { }";
    assert!(property_of(source, "C", "p").is_some());
    assert_eq!(declaring_line(source, "C", "p"), "class B<T> { p: T; }");
    assert_eq!(type_of(&format!("{source}\ndeclare const c: C; const x = c.p;"), "x"), "number");
    let plain = "class B { p: number; }\nclass C extends B { }";
    assert!(property_of(plain, "C", "p").is_some());
}

#[test]
fn generic_bases_keep_the_first_supplier_and_its_concrete_type() {
    // The old gap prevented accidentally skipping an unsupported B<T>. Now
    // both suppliers are supported: preserve the first origin even when the
    // later base conflicts, and observe concrete substitution when B is first.
    for argument in ["number", "string"] {
        let source = format!("interface A {{ p: number }}\ninterface B<T> {{ p: T }}\ninterface I extends A, B<{argument}> {{}}");
        assert_eq!(declaring_line(&source, "I", "p"), "interface A { p: number }");
        assert_eq!(type_of(&format!("{source}\ndeclare const i: I; const x = i.p;"), "x"), "number");
    }
    let reversed = "interface A { p: string }\ninterface B<T> { p: T }\ninterface I extends B<number>, A {}";
    assert_eq!(declaring_line(reversed, "I", "p"), "interface B<T> { p: T }");
    assert_eq!(type_of(&format!("{reversed}\ndeclare const i: I; const x = i.p;"), "x"), "number");
}

