                for (target, binding) in [
                    ("[{ c: 'right' }]", "[{ c: chosen = 'wrong' }]"),
                    ("[['right']]", "[[chosen = 'wrong']]"),
                    ("{ items: ['right'] }", "{ [key]: [chosen = 'wrong'] }"),
                ] {
