    // Red adapter: the current production getter only publishes bound IDs.
    fn publication(checker: &mut Checker<'_, '_>, receiver: crate::TypeId, name: &str) -> crate::symbol_access::SymbolRef {
        match checker.publication_property(receiver, receiver, name) {
            crate::member_publication::MemberQuery::Published { symbol, .. } => symbol,
            other => panic!("publication unavailable: {other:?}"),
        }
    }

    #[test]
    fn published_member_scalar_history_uses_actual_handles() {
        let source = "interface Base<T> { value:number } interface Left<U> extends Base<U> { left:U } interface Right<V> extends Base<V> { right:V } type Both=Left<string>&Right<number>; declare const receiver:Both; const probe=receiver.value;";
        let mut observed = Vec::new();
        for order in 0..3 {
            with_checker(source, |checker, root| {
                if order == 2 {
                    checker.check_source_file(root, crate::check::FileContext { ambient:false, has_parse_errors:false });
                }
                let receiver_symbol = checker.binder.lookup_local(root, "receiver").unwrap();
                let receiver = checker.get_type_of_symbol(receiver_symbol);
                if order == 1 {
                    let probe = checker.binder.lookup_local(root, "probe").unwrap();
                    checker.get_type_of_symbol(probe);
                }
                let first = publication(checker, receiver, "value");
                let view = checker.symbols.view(&first).unwrap();
                let private = view.flags().contains(tsr_binder::SymbolFlags::TRANSIENT);
                assert!(!view.check_flags().contains(crate::symbol_access::CheckFlags::INSTANTIATED), "composite clone is not an instantiation");
                println!("PUBLISHED_SCALAR order={order} private={private} symbol={first:?}");
                observed.push(private);
                for _ in 0..3 {
                    assert_eq!(publication(checker, receiver, "value"), first, "warm lookup must retain actual published handle");
                }
            });
        }
        assert_eq!(observed, [false,true,false], "native Single/Merged/Single history");
    }
