        // `5` matches neither `string` nor `false`, so the naked `T` is where
        // the candidate lands. Without the union arm this is a gap.
        assert_eq!(
            generic_call(
                "declare function f3<T>(x: string | false | T): T;\nconst c1 = f3(5);",
                "f3"
