    fn is_type_parameter_at_top_level(&mut self, id: TypeId, parameter: TypeId) -> bool {
        self.is_type_parameter_at_top_level_with_depth(id, parameter, 0)
    }

    fn is_type_parameter_at_top_level_with_depth(
        &mut self,
        id: TypeId,
        parameter: TypeId,
        depth: usize,
    ) -> bool {
