            let source=format!("class Base<T> {{ get value():number {{ return 0; }} set value(v:T) {{}} }} class Left<U> extends Base<U> {{}} class Right<V> extends Base<V> {{}} type Both={body}; declare const receiver:Both;");
            with_checker(&source, |checker,root| {
