    #[test]
    fn published_member_native_fixture_matrix() {
        use crate::symbol_access::CheckFlags;
        let generic = "interface Base<T> { value:T } interface Left<U> extends Base<U> { left:U } interface Right<V> extends Base<V> { right:V }";
        let accessor = "class Base<T> { get value():number { return 0; } set value(v:T) {} } class Left<U> extends Base<U> { declare left:U } class Right<V> extends Base<V> { declare right:V }";
        let rows = [
            ("shared-self", "interface Base { self:this } interface Left extends Base { left:number } interface Right extends Base { right:string } type Both=Left&Right;".to_owned(), "self", "single", "Both", "Both"),
            ("distinct-self", "interface Left { self:this;left:number } interface Right { self:this;right:string } type Both=Left&Right;".to_owned(), "self", "synthesized", "Left & Right", "Left & Right"),
            ("equal-generic", format!("{generic} type Both=Left<string>&Right<string>;"), "value", "single", "string", "string"),
            ("optional-generic", "interface Base<T> { value?:T } interface Left<U> extends Base<U> { left:U } interface Right<V> extends Base<V> { right:V } type Both=Left<string>&Right<string>;".to_owned(), "value", "single", "string", "string"),
            ("readonly-generic", "interface Base<T> { readonly value:T } interface Left<U> extends Base<U> { left:U } interface Right<V> extends Base<V> { right:V } type Both=Left<string>&Right<string>;".to_owned(), "value", "single", "string", "string"),
            ("private-common", "class Base<T> { private value!:T } class Left<U> extends Base<U> { declare left:U } class Right<V> extends Base<V> { declare right:V } type Both=Left<string>&Right<string>;".to_owned(), "value", "single", "string", "string"),
            ("unequal-generic", format!("{generic} type Both=Left<string>&Right<number>;"), "value", "synthesized", "never", "never"),
            ("distinct-value", "interface Left { value:string;left:number } interface Right { value:string;right:number } type Both=Left&Right;".to_owned(), "value", "synthesized", "string", "string"),
            ("accessor", format!("{accessor} type Both=Left<string>&Right<number>;"), "value", "merged", "number", "string"),
            ("accessor-reverse", format!("{accessor} type Both=Right<number>&Left<string>;"), "value", "merged", "number", "number"),
        ];
        let mut failures=Vec::new();
        for (case,body,property,want_kind,want_read,want_write) in rows {
            let source=format!("{body} declare const receiver:Both; const probe=receiver.{property};");
            for order in 0..3 {
                with_checker(&source, |checker, root| {
                    checker.apply_compiler_options(&tsr_core::CompilerOptions {
                        strict:tsr_core::Tristate::True,
                        exact_optional_property_types:tsr_core::Tristate::True,
                        target:tsr_core::ScriptTarget::ES2020,
                        ..tsr_core::CompilerOptions::default()
                    });
                    if order==2 { checker.check_source_file(root, crate::check::FileContext {ambient:false,has_parse_errors:false}); }
                    let receiver_symbol=checker.binder.lookup_local(root,"receiver").unwrap();
                    let receiver=checker.get_type_of_symbol(receiver_symbol);
                    if order==1 { let probe=checker.binder.lookup_local(root,"probe").unwrap(); checker.get_type_of_symbol(probe); }
                    let first=publication(checker,receiver,property);
                    let check=checker.symbols.view(&first).unwrap().check_flags();
                    let kind=if check.contains(CheckFlags::SYNTHETIC_PROPERTY) {"synthesized"}
                        else if checker.member_publication.links.get(&first).is_some_and(|l| l.containing.is_some()) {"merged"}
                        else {"single"};
                    let read=checker.publication_read(&first);
                    let write=checker.publication_write(&first);
                    // Native adapter asks getNonMissingTypeOfSymbol. Keep
                    // the raw read link unchanged and project missing here.
                    let optional=checker.publication_optional(&first);
                    let projected_read=if optional {checker.remove_missing_type(read)} else {read};
                    let read_text=checker.type_to_string(projected_read);
                    let write_text=checker.type_to_string(write);
                    let probe=checker.binder.lookup_local(root,"probe").unwrap();
                    let expression=checker.get_type_of_symbol(probe);
                    let expression_text=checker.type_to_string(expression);
                    println!("PUBLISHED_MATRIX case={case} order={order} kind={kind} read={read_text:?} write={write_text:?} expression={expression_text:?}");
                    if (kind,read_text.as_str(),write_text.as_str())!=(want_kind,want_read,want_write) {
                        failures.push(format!("{case}/{order}: {kind} {read_text} {write_text}"));
                    }
                    // Native's supplier reads retain the original alias; the
                    // synthesized result flattens both equal intersection reads.
                    if case=="distinct-self" {
                        let prepared=checker.publication_apparent(receiver);
                        let crate::TypeData::Intersection {types,..}=checker.store.get(prepared).data.clone() else { panic!("apparent intersection") };
                        assert_ne!(prepared,receiver);
                        for part in types {
                            let supplier=publication(checker,part,property);
                            assert_eq!(checker.publication_read(&supplier),receiver,"native supplier original-this identity");
                            assert_eq!(checker.publication_write(&supplier),receiver);
                        }
                        assert_ne!(read,receiver,"native result flattens the aliased intersection");
                        assert_eq!(expression,read);
                        assert_eq!(checker.member_publication.links[&first].containing,Some(prepared));
                    }
                    for _ in 0..3 { assert_eq!(publication(checker,receiver,property),first); }
                });
            }
        }
        assert!(failures.is_empty(), "native mismatches: {failures:?}");
    }

    #[test]
    fn published_member_clone_retains_links_without_merge_redirect() {
        use crate::symbol_access::CheckFlags;
        with_checker("interface Base<T> { value:number } interface Left<U> extends Base<U> {} interface Right<V> extends Base<V> {} type Both=Left<string>&Right<number>; declare const receiver:Both; const probe=receiver.value;", |checker,root| {
            let probe=checker.binder.lookup_local(root,"probe").unwrap();
            checker.get_type_of_symbol(probe);
            let receiver_symbol=checker.binder.lookup_local(root,"receiver").unwrap();
            let receiver=checker.get_type_of_symbol(receiver_symbol);
            let clone=publication(checker,receiver,"value");
            assert_eq!(checker.publication_target(&clone),clone);
            assert!(!checker.symbols.view(&clone).unwrap().check_flags().contains(CheckFlags::INSTANTIATED));
            let links=checker.member_publication.links[&clone].clone();
            let first=links.target.unwrap();
            assert_ne!(clone,first);
            assert!(checker.symbols.view(&first).unwrap().check_flags().contains(CheckFlags::INSTANTIATED));
            assert_eq!(links.mapper,checker.member_publication.links[&first].mapper);
            assert_eq!(links.containing,Some(checker.publication_apparent(receiver)));
            let write=checker.publication_write(&first);
            assert_eq!(links.write,Some(write));
            let root_symbol=checker.publication_target(&first);
            assert_eq!(checker.symbols.merged_symbol(&root_symbol).unwrap(),root_symbol);
            let parent=checker.symbols.view(&clone).unwrap().parent().unwrap();
            assert_eq!(checker.symbols.view(&parent).unwrap().name(),"Base");
            assert_eq!(checker.symbols.view(&clone).unwrap().declarations(),checker.symbols.view(&root_symbol).unwrap().declarations());
            let base=checker.binder.lookup_local(root,"Base").unwrap();
            // Deliberate reset notification, distinct from natural TS2310.
            checker.publication_reset_target(base);
            assert_eq!(publication(checker,receiver,"value"),clone);
        });
    }

