    // Red adapter: the current production getter only publishes bound IDs.
    fn publication(checker: &mut Checker<'_, '_>, receiver: crate::TypeId, name: &str) -> crate::symbol_access::SymbolRef {
        match checker.publication_property(receiver, receiver, name) {
