import json
from pathlib import Path
r=Path(Path("/tmp/tsr-member-thisless-path").read_text().strip()); p=r/"source/crates/tsr-checker/tests/members.rs"; before=p.read_text(); text=before
start=text.index("    // A member that genuinely exists on the cycle"); end=text.index("\n}\n",start)
text=text[:start]+'''    // Native getBaseTypes / resolveBaseTypesOfClass (5b1047d checker.go:19167,
    // :19220) reject a circular class base rather than walk its declarations.
    // The old assertion expected the shortcut walker to return B.b; the fresh
    // native public one-hop control reports TS2339 for A.b. Own A.a remains.
    let source = "class A extends B { a: number; }\\nclass B extends A { b: string; }";
    assert_eq!(property_of(source, "A", "b"), None);
    assert!(property_of(source, "A", "a").is_some());
    // Refusing a cyclic base is distinct from refusing all inheritance.
    let acyclic = "class B { b: string; }\\nclass A extends B { a: number; }";
    assert_eq!(declaring_line(acyclic, "A", "b"), "class B { b: string; }");'''+text[end:]
start=text.index("fn a_base_with_type_arguments_is_a_gap_rather_than_an_uninstantiated_answer()"); end=text.index("\n// ---------------------------------------------------------------------------",start)
text=text[:start]+'''fn a_generic_base_keeps_its_declaration_origin_and_instantiated_property_type() {
    // This formerly pinned an honest unported gap. Native class reference
    // admission (5b1047d checker.go:19220) applies B<number>; the new publication
    // path now owns both the origin and the concrete member read. Testing only
    // the returned name would hide a raw T in place of number.
    let source = "class B<T> { p: T; }\\nclass C extends B<number> { }";
    assert!(property_of(source, "C", "p").is_some());
    assert_eq!(declaring_line(source, "C", "p"), "class B<T> { p: T; }");
    assert_eq!(type_of(&format!("{source}\\ndeclare const c: C; const x = c.p;"), "x"), "number");
    let plain = "class B { p: number; }\\nclass C extends B { }";
    assert!(property_of(plain, "C", "p").is_some());
}

#[test]
fn generic_bases_keep_the_first_supplier_and_its_concrete_type() {
    // The old gap prevented accidentally skipping an unsupported B<T>. Now
    // both suppliers are supported: preserve the first origin even when the
    // later base conflicts, and observe concrete substitution when B is first.
    for argument in ["number", "string"] {
        let source = format!("interface A {{ p: number }}\\ninterface B<T> {{ p: T }}\\ninterface I extends A, B<{argument}> {{}}");
