import collections,hashlib,json,os,re,subprocess,time
from pathlib import Path
root=Path(Path('/tmp/tsr-member-thisless-path').read_text());binaries=json.loads((root/'final-binaries.json').read_text());sha=lambda b:hashlib.sha256(b).hexdigest()
def parsed(raw,diagnostic):
    text=raw.decode();pattern=r'(?m)^[^\t\r\n]+\t(?:RIGHT|WRONG|EMPTY_RIGHT|EMPTY_WRONG)\t' if diagnostic else r'(?m)^[^\t\r\n]+:\d+:\d+\t(?:RIGHT|GAP|WRONG)\t';starts=list(re.finditer(pattern,text));assert starts and starts[0].start()==0
    rows=[text[m.start():(starts[i+1].start() if i+1<len(starts) else len(text))].removesuffix('\n') for i,m in enumerate(starts)];table={r.split('\t',1)[0]:r for r in rows};assert len(rows)==len(table);return table
env={k:v for k,v in os.environ.items() if not k.startswith(('TSR_','TSGO_','RAYON_'))};env['RAYON_NUM_THREADS']='4';runs=[];comparisons={}
for diagnostic in [False,True]:
    kind='diagverdictdump' if diagnostic else 'verdictdump';suffix='diagnostics' if diagnostic else 'types';tables={}
    for mode in ['baseline','final']:
        build=next(b for b in binaries['builds'] if b['mode']==mode);binary=build['outputs'][kind];exe=Path(binary['path']);assert sha(exe.read_bytes())==binary['sha256'];cmd=['rtk','proxy',str(exe)];start=time.monotonic()
        with (root/(mode+'-'+suffix+'.tsv')).open('wb') as out,(root/(mode+'-'+suffix+'.stderr')).open('wb') as err:
            p=subprocess.Popen(cmd,cwd=root/'source',env=env,stdout=out,stderr=err);print(json.dumps({'mode':mode,'kind':suffix,'pid':p.pid,'command':cmd}),flush=True);rc=p.wait(timeout=900)
        raw=(root/(mode+'-'+suffix+'.tsv')).read_bytes();table=parsed(raw,diagnostic);stderr=(root/(mode+'-'+suffix+'.stderr')).read_text();assert rc==0
        if not diagnostic:assert int(re.search(r'TOTAL (\d+)',stderr).group(1))==len(table)
        run={'mode':mode,'kind':suffix,'command':cmd,'pid':p.pid,'returncode':rc,'elapsed_seconds':time.monotonic()-start,'stdout_sha256':sha(raw),'binary_sha256':binary['sha256'],'row_count':len(table),'verdict_counts':dict(collections.Counter(r.split('\t',2)[1] for r in table.values())),'stderr':stderr};runs.append(run);tables[mode]=table;(root/'full-corpus-progress.json').write_text(json.dumps({'runs':runs,'unfiltered':True,'threads':4},indent=2)+'\n');print(json.dumps({k:run[k] for k in ['mode','kind','returncode','row_count','verdict_counts']}),flush=True)
    before,after=tables['baseline'],tables['final'];assert before.keys()==after.keys()
    if diagnostic:assert all(before[k].split('\t',3)[2]==after[k].split('\t',3)[2] for k in before)
    changed=[{'key':k,'before':before[k],'after':after[k]} for k in before if before[k]!=after[k]];passing={'RIGHT','EMPTY_RIGHT'} if diagnostic else {'RIGHT'};lost=[r for r in changed if r['before'].split('\t',2)[1] in passing and r['after'].split('\t',2)[1] not in passing]
    summary={'row_count':len(before),'changed_rows':len(changed),'transitions':dict(collections.Counter(r['before'].split('\t',2)[1]+'->'+r['after'].split('\t',2)[1] for r in changed)),'previous_right_losses':len(lost),'loss_case_counts':dict(collections.Counter(r['key'] if diagnostic else r['key'].rsplit(':',2)[0] for r in lost))};comparisons[suffix]={'summary':summary,'changed_rows':changed};print(json.dumps({suffix:summary}),flush=True)
    (root/'full-corpus-partial.json').write_text(json.dumps({'runs':runs,'comparisons':comparisons,'unfiltered':True,'no_performance_claim':True},indent=2)+'\n')
(root/'full-corpus.json').write_text(json.dumps({'source_revision':binaries['source_revision'],'native_revision':binaries['native_revision'],'fixture_revision':binaries['fixture_revision'],'runs':runs,'comparisons':comparisons,'unfiltered':True,'threads':4,'fresh_baseline_and_candidate_builds':True,'no_performance_claim':True},indent=2)+'\n')
